// BTI QTO Calculation Logic
const data = $input.all();
const qtoResults = {
  total_area: 0,
  total_perimeter: 0,
  entities_by_layer: {},
  entities_by_type: {},
  windows_count: 0,
  doors_count: 0,
  rooms: []
};

for (const item of data) {
  const row = item.json;

  // Sum total area and perimeter
  if (row.Area && !isNaN(row.Area)) {
    qtoResults.total_area += parseFloat(row.Area);
  }
  if (row.Perimeter && !isNaN(row.Perimeter)) {
    qtoResults.total_perimeter += parseFloat(row.Perimeter);
  }

  // Group by layer
  const layer = row.Layer || 'unknown';
  if (!qtoResults.entities_by_layer[layer]) {
    qtoResults.entities_by_layer[layer] = { count: 0, area: 0, perimeter: 0 };
  }
  qtoResults.entities_by_layer[layer].count++;
  if (row.Area) qtoResults.entities_by_layer[layer].area += parseFloat(row.Area || 0);
  if (row.Perimeter) qtoResults.entities_by_layer[layer].perimeter += parseFloat(row.Perimeter || 0);

  // Group by entity type
  const entityType = row.EntityType || row.Type || 'unknown';
  if (!qtoResults.entities_by_type[entityType]) {
    qtoResults.entities_by_type[entityType] = { count: 0, area: 0 };
  }
  qtoResults.entities_by_type[entityType].count++;
  if (row.Area) qtoResults.entities_by_type[entityType].area += parseFloat(row.Area || 0);

  // Count windows and doors
  const layerLower = layer.toLowerCase();
  const typeLower = entityType.toLowerCase();
  if (layerLower.includes('window') || typeLower.includes('window')) {
    qtoResults.windows_count++;
  }
  if (layerLower.includes('door') || typeLower.includes('door')) {
    qtoResults.doors_count++;
  }

  // Extract room information
  if (layerLower.includes('room') || typeLower.includes('room') || layerLower.includes('space')) {
    qtoResults.rooms.push({
      name: row.Name || row.RoomName || 'Unnamed Room',
      area: parseFloat(row.Area || 0),
      perimeter: parseFloat(row.Perimeter || 0)
    });
  }
}

// Round values
qtoResults.total_area = Math.round(qtoResults.total_area * 100) / 100;
qtoResults.total_perimeter = Math.round(qtoResults.total_perimeter * 100) / 100;

return [{ json: qtoResults }];
